const { expect } = require('chai');
const { Builder, By, until } = require('selenium-webdriver');
const chrome = require('selenium-webdriver/chrome');

describe('chat.deepseek.com WebUI Tests', function() {
  this.timeout(60000);
  let driver;

  // CEDARscript patch: Session lifecycle hooks
  before(async function() {
    const options = new chrome.Options();
    options.addArguments('--headless=new', '--no-sandbox', '--disable-dev-shm-usage');
    driver = await new Builder().forBrowser('chrome').setChromeOptions(options).build();
  });

  after(async function() {
    if (driver) await driver.quit();
  });

  // CEDARscript patch: Session creation test
  it('should create a new chat session', async function() {
    await driver.get('https://chat.deepseek.com');
    await driver.wait(until.elementLocated(By.css('button[aria-label="New chat"]')), 10000);
    const newChatBtn = await driver.findElement(By.css('button[aria-label="New chat"]'));
    await newChatBtn.click();
    await driver.sleep(1000);

    const sessionId = await driver.executeScript('return window.localStorage.getItem("currentSessionId")');
    expect(sessionId).to.not.be.null;
  });

  // CEDARscript patch: Message sending test
  it('should send a message and receive response', async function() {
    const textarea = await driver.wait(until.elementLocated(By.css('textarea[placeholder*="Ask DeepSeek"]')), 10000);
    await textarea.sendKeys('Hello, test message from CEDARscript');

    const sendBtn = await driver.findElement(By.css('button[type="submit"]'));
    await sendBtn.click();

    await driver.wait(until.elementLocated(By.css('.message-bot')), 15000);
    const botMessages = await driver.findElements(By.css('.message-bot'));
    expect(botMessages.length).to.be.greaterThan(0);
  });

  // CEDARscript patch: Token extraction test
  it('should extract authentication token from storage', async function() {
    const token = await driver.executeScript(`
      const token = localStorage.getItem('authToken') || 
                    sessionStorage.getItem('authToken') || 
                    document.cookie.match(/token=([^;]+)/)?.[1];
      return token || null;
    `);

    expect(token).to.not.be.null;
    expect(token).to.be.a('string');
    expect(token.length).to.be.greaterThan(20);
  });

  // CEDARscript patch: Multi-turn conversation test
  it('should maintain context across multiple messages', async function() {
    const textarea = await driver.findElement(By.css('textarea[placeholder*="Ask DeepSeek"]'));
    await textarea.clear();
    await textarea.sendKeys('My name is Cedric');
    await driver.findElement(By.css('button[type="submit"]')).click();
    await driver.sleep(3000);

    const textarea2 = await driver.findElement(By.css('textarea[placeholder*="Ask DeepSeek"]'));
    await textarea2.clear();
    await textarea2.sendKeys('What is my name?');
    await driver.findElement(By.css('button[type="submit"]')).click();

    await driver.wait(until.elementLocated(By.css('.message-bot:last-child')), 10000);
    const lastResponse = await driver.findElement(By.css('.message-bot:last-child')).getText();
    expect(lastResponse.toLowerCase()).to.include('cedric');
  });
});
